            modelBuilder.Entity("Avalon.Domain.World.LocalizedText", b =>
                {
                    b.Property<int>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("integer");

                    NpgsqlPropertyBuilderExtensions.UseIdentityByDefaultColumn(b.Property<int>("Id"));

                    b.Property<string>("Text")
                        .IsRequired()
                        .HasColumnType("text");

                    b.HasKey("Id");

                    b.ToTable("LocalizedTexts", (string)null);

                    b.HasData(
                        new
                        {
                            Id = 1,
                            Text = "The wold grows darker each season, {name}. There are seasons now where it does not lighten at all."
                        },
                        new
                        {
                            Id = 2,
                            Text = "Something took root at its heart. The beasts feel it before we do — they change, and then they do not change back."
                        },
                        new
                        {
                            Id = 3,
                            Text = "Some return. Not all of what returns is who left."
                        },
                        new
                        {
                            Id = 4,
                            Text = "Steel holds. Wood rots. Remember which one you are carrying when you walk under those trees."
                        },
                        new
                        {
                            Id = 5,
                            Text = "Once, and I came back for the anvil rather than the view. A {class} might fare better than a smith did."
                        },
                        new
                        {
                            Id = 6,
                            Text = "Room's upstairs, {name}, stew's on, and I ask no questions about the state of your boots."
                        },
                        new
                        {
                            Id = 7,
                            Text = "What changed?"
                        },
                        new
                        {
                            Id = 8,
                            Text = "And the ones who go in?"
                        },
                        new
                        {
                            Id = 9,
                            Text = "Have you been in?"
                        },
                        new
                        {
                            Id = 10,
                            Text = "Farewell."
                        },
                        new
                        {
                            Id = 11,
                            Text = "Warrior"
                        },
                        new
                        {
                            Id = 12,
                            Text = "Wizard"
                        },
                        new
                        {
                            Id = 13,
                            Text = "Hunter"
                        },
                        new
                        {
                            Id = 14,
                            Text = "Cleric"
                        },
                        new
                        {
                            Id = 15,
                            Text = "Coin and keepsakes both, {name}. The vault keeps what the road would take."
                        },
                        new
                        {
                            Id = 16,
                            Text = "Open my bank."
                        },
                        new
                        {
                            Id = 17,
                            Text = "Steel, stave or string, traveller. What'll it be?"
                        },
                        new
                        {
                            Id = 18,
                            Text = "Every blade here I hammered myself. Won't match what the forest spits out, but it'll keep you breathing till you find better."
                        },
                        new
                        {
                            Id = 19,
                            Text = "Mind the rack. Looking to cover something?"
                        },
                        new
                        {
                            Id = 20,
                            Text = "Plate, leather, cloth. I fit every trade. Buy it plain, earn it fancy."
                        },
                        new
                        {
                            Id = 21,
                            Text = "Potions, scrolls, supplies. And I'll take what you've no use for."
                        },
                        new
                        {
                            Id = 22,
                            Text = "I buy anything that isn't nailed to you. Fair prices, mostly."
                        },
                        new
                        {
                            Id = 23,
                            Text = "What do you deal in?"
                        },
                        new
                        {
                            Id = 24,
                            Text = "Show me your wares."
                        },
                        new
                        {
                            Id = 25,
                            Text = "Thinning the Herd"
                        },
                        new
                        {
                            Id = 26,
                            Text = "The Thornback Boars have grown bold, {name}. They root up the paths and gore anyone who strays. Cull six of them before someone else is carried home."
                        },
                        new
                        {
                            Id = 27,
                            Text = "Six fewer tusks in the undergrowth. The paths will breathe easier for it."
                        },
                        new
                        {
                            Id = 28,
                            Text = "Thornback Boars slain"
                        },
                        new
                        {
                            Id = 29,
                            Text = "Tusks for Borin"
                        },
                        new
                        {
                            Id = 30,
                            Text = "Borin swears boar tusk takes an edge like nothing else. Bring him four tusks from the Thornback Boars; he will make it worth your while."
                        },
                        new
                        {
                            Id = 31,
                            Text = "Four good tusks! These will temper into something fine. Take these for the road."
                        },
                        new
                        {
                            Id = 32,
                            Text = "Boar Tusks gathered"
                        },
                        new
                        {
                            Id = 33,
                            Text = "The Alpha's Howl"
                        },
                        new
                        {
                            Id = 34,
                            Text = "Something leads the pack now, {name}. Thin the wolves and the husks at the forest's edge, tell Marta what you have seen, then find the Bramblemaw Alpha and end it."
                        },
                        new
                        {
                            Id = 35,
                            Text = "The howling has stopped. The forest is quieter than it has been in a long while. Wear this, {class}; you earned it."
                        },
                        new
                        {
                            Id = 36,
                            Text = "Grey Fen Wolves slain"
                        },
                        new
                        {
                            Id = 37,
                            Text = "Husks of the Wold destroyed"
                        },
                        new
                        {
                            Id = 38,
                            Text = "Speak with Marta Ledgerwell"
                        },
                        new
                        {
                            Id = 39,
                            Text = "Bramblemaw Alpha slain"
                        },
                        new
                        {
                            Id = 40,
                            Text = "Clear the forest's edge."
                        },
                        new
                        {
                            Id = 41,
                            Text = "Tell Marta what you have seen."
                        },
                        new
                        {
                            Id = 42,
                            Text = "Hunt down the Bramblemaw Alpha."
                        },
                        new
                        {
                            Id = 43,
                            Text = "Wings for the Still"
                        },
                        new
                        {
                            Id = 44,
                            Text = "The Blightfly Swarmlings drone over the wold day and night, {name}, and the dust on their wings settles a fever better than any root I sell. Bring me six wings for my still, whole if you can manage it."
                        },
                        new
                        {
                            Id = 45,
                            Text = "Six good wings. That dust will see a few fevers through the cold months. Take these for your trouble."
                        },
                        new
                        {
                            Id = 46,
                            Text = "Blightfly Wings gathered"
                        },
                        new
                        {
                            Id = 47,
                            Text = "Pelts Before Frost"
                        },
                        new
                        {
                            Id = 48,
                            Text = "Frost comes early under those trees, and the Grey Fen Wolves wear the thickest coats in the wold. Bring me eight of their pelts and I will line half the town's cloaks before the first freeze."
                        },
                        new
                        {
                            Id = 49,
                            Text = "Eight pelts, and barely a nick in them. The town will be warmer for it, {name}."
                        },
                        new
                        {
                            Id = 50,
                            Text = "Fen Wolf Pelts gathered"
                        },
                        new
                        {
                            Id = 51,
                            Text = "What the Husks Carry"
                        },
                        new
                        {
                            Id = 52,
                            Text = "Travellers swear the Husks of the Wold still clutch scraps of paper, {name}: pages from a ledger, with Marta's mark on them. Put down eight of those things and bring whatever pages you find to Marta at the bank."
                        },
                        new
                        {
                            Id = 53,
                            Text = "These are mine. Accounts from a caravan that never came back. I owe you more than coin for this, {name}, but coin is what I have."
                        },
                        new
                        {
                            Id = 54,
                            Text = "Ledger Pages recovered"
                        },
                        new
                        {
                            Id = 55,
                            Text = "Heartwood"
                        },
                        new
                        {
                            Id = 56,
                            Text = "Old Tuskroot has walked the wold longer than this town has stood, and the wood at its heart is harder than iron. Bring me that heartwood, {class}, and I will set it in something worth wearing."
                        },
                        new
                        {
                            Id = 57,
                            Text = "Now that is heartwood. Hold out your hand; this one was made to fit it."
                        },
                        new
                        {
                            Id = 58,
                            Text = "Tuskroot Heartwood taken"
                        },
                        new
                        {
                            Id = 59,
                            Text = "Mother of Thorns"
                        },
                        new
                        {
                            Id = 60,
                            Text = "The Bramblemaw Alphas answer to something deeper in the wold, {name}. Speak with Garrick first: he has forged against thorns before. Then go to the heart of the forest, bring down two of the Alphas and end Mother Bramble, the Mother of Thorns."
                        },
                        new
                        {
                            Id = 61,
                            Text = "The wold is breathing again. It will remember what you did, and so will we. Wear this, {class}."
                        },
                        new
                        {
                            Id = 62,
                            Text = "Speak with Garrick Emberforge"
                        },
                        new
                        {
                            Id = 63,
                            Text = "Bramblemaw Alphas slain"
                        },
                        new
                        {
                            Id = 64,
                            Text = "Bramble Heart taken"
                        },
                        new
                        {
                            Id = 65,
                            Text = "Ask Garrick how to face the thorns."
                        },
                        new
                        {
                            Id = 66,
                            Text = "Break the Bramblemaw Alphas' hold and cut out the Bramble Heart."
                        },
                        new
                        {
                            Id = 67,
                            Text = "The Lost Caravan"
                        },
                        new
                        {
                            Id = 68,
                            Text = "Those pages were the last of the caravan's accounts, {name}. Somewhere in the wold its strongbox still lies where the wagons fell. Find it and open it, and tell me what it holds."
                        },
                        new
                        {
                            Id = 69,
                            Text = "So that is how it ended. Thank you, {name}. Now the town knows, and I can stop waiting for wagons that will never come."
                        },
                        new
                        {
                            Id = 70,
                            Text = "Caravan strongbox opened"
                        },
                        new
                        {
                            Id = 71,
                            Text = "The caravan's fate posted"
                        },
                        new
                        {
                            Id = 72,
                            Text = "Find the caravan's strongbox in the forest."
                        },
                        new
                        {
                            Id = 73,
                            Text = "Pin the caravan's fate to the notice board in Glimmerdell."
                        },
                        new
                        {
                            Id = 74,
                            Text = "Tell Marta what you found."
                        },
                        new
                        {
                            Id = 75,
                            Text = "Boar Cull"
                        },
                        new
                        {
                            Id = 76,
                            Text = "The Thornback Boars are rooting up every path into Glimmerdell again, {name}, and every hide they tear is one I end up patching. Thin them out: fifteen will do for today. Come back tomorrow; there will be more."
                        },
                        new
                        {
                            Id = 77,
                            Text = "Fifteen fewer tusks in the hedges. Here, for your trouble. They will be back by morning, mind. They always are."
                        },
                        new
                        {
                            Id = 78,
                            Text = "Thornback Boars culled"
                        },
                        new
                        {
                            Id = 79,
                            Text = "Earn It Fancy"
                        },
                        new
                        {
                            Id = 80,
                            Text = "The pelts you brought me lined half the town's cloaks, {name}, and not one of them was cut for you. That wants mending. But you know my rule: buy it plain, earn it fancy. Put down six Grey Fen Wolves and the Bramblemaw Alpha that leads them, and I will fit you myself."
                        },
                        new
                        {
                            Id = 81,
                            Text = "The pack thinned and its alpha with it. You earned it fancy, {class}. Take your pick; I made every piece on that rack to be fought in."
                        });
