                        new
                        {
                            TextId = 26,
                            Locale = "ptPT",
                            Text = "Os Thornback Boars ganharam ousadia, {name}. Revolvem os caminhos e atacam com as presas quem se aproxima. Abate seis deles antes que mais alguém tenha de ser trazido para casa."
                        },
