                        },
                        new
                        {
                            TextId = 28,
                            Locale = "ptPT",
                            Text = "Thornback Boars abatidos"
                        },
                        new
                        {
                            TextId = 29,
                            Locale = "ptPT",
                            Text = "Presas para o Borin"
                        },
                        new
                        {
                            TextId = 30,
                            Locale = "ptPT",
                            Text = "O Borin jura que a presa de javali ganha gume como mais nada. Leva-lhe quatro presas dos Thornback Boars; ele há de fazer valer a pena."
                        },
                        new
