                            TextId = 55,
                            Locale = "ptPT",
                            Text = "Cerne"
                        },
                        new
                        {
                            TextId = 56,
                            Locale = "ptPT",
                            Text = "O Old Tuskroot anda pela mata há mais tempo do que esta vila existe, e a madeira do seu coração é mais dura do que o ferro. Traz-me esse cerne, {class}, e engasto-o em algo que valha a pena usar."
                        },
