                            Locale = "ptPT",
                            Text = "Abate de Javalis"
                        },
                        new
                        {
                            TextId = 76,
                            Locale = "ptPT",
                            Text = "Os Thornback Boars voltaram a revolver todos os caminhos para Glimmerdell, {name}, e cada couro que rasgam acaba remendado por mim. Desbasta-os: quinze chegam por hoje. Volta amanhã, que haverá mais."
                        },
                        new
                        {
                            TextId = 77,
                            Locale = "ptPT",
                            Text = "Menos quinze presas nas sebes. Toma, pelo teu trabalho. Pela manhã estão de volta, atenção. Voltam sempre."
                        },
                        new
                        {
                            TextId = 78,
                            Locale = "ptPT",
                            Text = "Thornback Boars abatidos"
                        },
                        new
                        {
                            TextId = 79,
                            Locale = "ptPT",
                            Text = "Ganha-o Vistoso"
                        },
                        new
                        {
                            TextId = 80,
                            Locale = "ptPT",
                            Text = "As peles que me trouxeste forraram metade das capas da vila, {name}, e nenhuma foi talhada para ti. Isso tem de se remediar. Mas conheces a minha regra: compra-o simples, ganha-o vistoso. Abate seis Grey Fen Wolves e o Bramblemaw Alpha que os lidera, e eu própria tiro-te as medidas."
                        },
                        new
                        {
                            TextId = 81,
                            Locale = "ptPT",
                            Text = "A alcateia desbastada, e o alfa com ela. Ganhaste-o vistoso, {class}. Escolhe a tua peça; fiz cada uma daquelas para aguentar uma luta."
                        });
